  ZimmCartItemActions,
  ZimmCartEmptyState,
  ZimmBenefits,
  ZimmCountryLanguageMismatch,
  ZimmCartButtonGroup,
  ZimmTable,
  ZimmAccordion,
  ZimmFiltersDrawerContent,
};

import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

type ScrollAreaContextValue = {
  /** Whether `scrollArea` has been scrolled past `body`'s own bottom edge — i.e. whether the
   *  footer slot (Zimmermann-benefits, SFCC-317) is at least partially revealed. Consumed by
   *  cartDrawerContainer.tsx's own items Stack to enforce Marcel's own direct rule, 2026-09-22:
   *  scrolling up must fully re-hide the footer (this flips back to `false`) before the items
   *  column's own independent scroll responds again. Native nested-scroll bubbling alone can't
   *  guarantee that on its own: which element a wheel/trackpad gesture actually scrolls depends
   *  on cursor position, not on a "which phase are we in" rule — so the items column needs to
   *  actively stop being scrollable itself while this is `true`, forcing every scroll gesture
   *  (regardless of where the cursor happens to be) to reach `scrollArea` instead, until it's
   *  back at the top. */
  isFooterRevealed: boolean;
  /** Reports whether the items column's own internal scroll has reached its own bottom edge.
   *  The mirror-image half of `isFooterRevealed`, added per Marcel's own direct correction,
   *  2026-09-22: the *first* round of this feature only locked the items column while the footer
   *  was revealed — it never stopped `scrollArea` itself from being scrolled straight to the
   *  footer by a gesture that never touched the items column at all (cursor over the totals
   *  column, or the gutter between them, has nothing of its own to scroll, so it bubbles to
   *  `scrollArea` immediately regardless of the items column's own position). Gates
   *  `scrollArea`'s own `overflowY` below: locked until this reports `true`, so revealing the
   *  footer stays unreachable no matter where a scroll gesture actually originates, not just
   *  when it happens to start over the items column. */
  onLhsAtBottomChange: (atBottom: boolean) => void;
};

/**
 * Context, not props: `body`'s actual content is `children`, opaque to this component — the
 * items Stack that needs `isFooterRevealed` and provides `onLhsAtBottomChange` is rendered
 * several layers down, inside cartDrawerContainer.tsx, not here. The two values flow in opposite
 * directions (down to the items column; back up from it), which is exactly what a callback
 * threaded through Context — rather than a plain prop — is for: Context can't carry a value
 * "up" the tree any more than a prop can, so the items column reports its own state by calling
 * a function this component owns, instead of this component reading a ref it has no access to.
 */
const ScrollAreaContext = createContext<ScrollAreaContextValue>({
  isFooterRevealed: false,
  onLhsAtBottomChange: () => {},
});

/** See `ScrollAreaContext`'s own doc comment. Defaults to `false` for any consumer rendered
 *  outside a real `ZimmCartDrawer` (there is currently only one real consumer: the items Stack
 *  in cartDrawerContainer.tsx). */
export const useIsFooterRevealed = () => useContext(ScrollAreaContext).isFooterRevealed;

/** See `ScrollAreaContext`'s own doc comment. Defaults to a no-op outside a real
 *  `ZimmCartDrawer` — calling it is harmless, just unobserved. */
export const useReportLhsAtBottom = () => useContext(ScrollAreaContext).onLhsAtBottomChange;

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Total quantity across every line in the bag (not the number of distinct products) — see
   *  cartDrawerContainer.tsx's own 2026-09-22 doc note on why: neither Figma nor this component's
   *  own original doc comment (which wrongly claimed "line items" with no cited source) settled
   *  it, so it's sourced from production www.zimmermann.com's own header behaviour instead. Drives
   *  the header title only ("BAG • {itemCount}" vs "YOUR BAG IS EMPTY") — see `children`'s own doc
   *  below for the empty-vs-populated body. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items — or the empty-state body. This organism owns no item-rendering logic and
   *  no empty-vs-populated decision itself: it renders whatever `children` it is given,
   *  unconditionally, regardless of `itemCount`. The caller (`cartDrawerContainer.tsx`, SFCC-11
   *  plan step 4.6) decides between the real item list and `ZimmCartEmptyState`. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no message aggregation. Those remain separate,
 * later commits in this same plan — this organism is exercised only via its own Storybook
 * stories today. (Corrected 2026-09-21, SFCC-11 plan step 4.6: this paragraph used to also list
 * "no real empty-state body" here — no longer true. This component itself never owned that
 * decision; it renders whatever `children` it is given unconditionally. The real empty-state
 * body — deciding between the item list and `ZimmCartEmptyState` — is `cartDrawerContainer.tsx`'s
 * job, per `ZimmCartDrawerProps.children`'s own doc above.)
 *
 * Figma-fidelity audit fix, 2026-09-19: `ZimmDrawer`'s `title` was passed with no `titleStyle`,
 * so it silently took that prop's default (`'large'` → `heading1`, 24px) instead of the Figma
 * spec for this header ("BAG • #", 14px medium — `body2Strong`). Measured live before the fix:
 * 24px/400/32px against the 14px/500 spec. `ZimmDrawer` itself already supports both correctly
 * (`titleStyle="small"` → `body2Strong`, confirmed against `typography.ts`) — this was a missing
 * prop at the call site, not a defect in `ZimmDrawer`.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  // See ScrollAreaContext's own doc comment above for why this lives here (scrollArea's real
  // DOM node) rather than in cartDrawerContainer.tsx, which never sees it directly.
  //
  // A callback ref, not a plain useRef + empty-deps useEffect: confirmed live (a real, temporary
  // debug log, not assumed) that Chakra's Drawer/Modal mounts its portal content one render pass
  // *after* ZimmCartDrawer's own initial mount, so a plain ref is still `null` — and
  // querySelector confirms the element itself doesn't exist in the DOM yet either — at the exact
  // moment an empty-deps effect would run. A callback ref fires whenever React actually attaches
  // (or detaches) the DOM node for this JSX position, whenever that turns out to be, not just
  // once on this component's own first render.
  const [scrollAreaEl, setScrollAreaEl] = useState<HTMLDivElement | null>(null);
  const scrollAreaRefCallback = useCallback((node: HTMLDivElement | null) => setScrollAreaEl(node), []);
  const [isFooterRevealed, setIsFooterRevealed] = useState(false);
  // Mirror-image state to isFooterRevealed above — see ScrollAreaContextValue's own doc comment.
  // Starts `false` (conservative: scrollArea starts locked) but the items column's own effect
  // (cartDrawerContainer.tsx) reports its real value immediately on mount, not just on its first
  // scroll — so a short cart with nothing to scroll internally still unlocks scrollArea from the
  // very first render, rather than staying wrongly locked with no scroll event left to fire.
  const [isLhsAtBottom, setIsLhsAtBottom] = useState(false);

  useEffect(() => {
    if (!scrollAreaEl) return;
    // > 0, not >= some threshold: any real scroll past body's own bottom edge means the footer
    // has started to show. React's own setState bails out when the value hasn't actually
    // changed, so this needs no manual guard against firing on every scroll tick.
    const handleScroll = () => setIsFooterRevealed(scrollAreaEl.scrollTop > 0);
    scrollAreaEl.addEventListener('scroll', handleScroll);
    return () => scrollAreaEl.removeEventListener('scroll', handleScroll);
  }, [scrollAreaEl]);

  // Stable across renders except when isFooterRevealed itself changes — setIsLhsAtBottom is
  // already stable by React's own guarantee, so this only avoids handing the items column a new
  // function/object identity on every unrelated re-render of this component.
  const scrollAreaContextValue = useMemo(
    () => ({ isFooterRevealed, onLhsAtBottomChange: setIsLhsAtBottom }),
    [isFooterRevealed],
  );

  return (
    <ZimmDrawer
      isOpen={isOpen}
      onClose={onClose}
      size="xLarge"
      title={title}
      titleStyle="small"
      finalFocusRef={finalFocusRef}
    >
      {/* 1:1 Figma-alignment audit fix, 2026-09-22 — see zimmCartDrawer.css.ts's `container`/
          `scrollArea` doc comments for why messages sits outside this real flex column while
          body/footer sit inside a second, real scroll container of their own, distinct from
          both ZimmDrawer's own outer scroll wrapper and body's own separate, independent
          items-column scroll (cartDrawerContainer.tsx). */}
      <chakra.div __css={styles.container}>
        <chakra.div __css={styles.messages}>{messages}</chakra.div>
        {/* data-testid: a generic layout container with no semantic role of its own — see
            .claude/rules/testing.md's Page Object Model selector priority, "complex layout
            blocks" — used by this component's own suite to simulate a real scroll position. */}
        <chakra.div
          __css={styles.scrollArea}
          // 1:1 Figma-alignment audit fix, 2026-09-22 round 2 (Marcel's direct correction): the
          // recipe's own `overflowY: 'auto'` (zimmCartDrawer.css.ts) is the Storybook-safe
          // fallback with no scroll-lock wiring behind it — this sx override is what actually
          // gates it in the real app, taking precedence over `__css` per Chakra's own style-prop
          // precedence. Locked (`hidden`) until the items column reports it has reached its own
          // bottom edge, regardless of which element under the cursor a scroll gesture actually
          // lands on. This does not stop the items column's own internal scroll from working
          // while locked: overflow:hidden on an ancestor only stops that ancestor from scrolling
          // itself, not a descendant that establishes its own independent overflow:auto.
          sx={{ overflowY: isLhsAtBottom ? 'auto' : 'hidden' }}
          ref={scrollAreaRefCallback}
          data-testid="cart-scroll-area"
        >
          <ScrollAreaContext.Provider value={scrollAreaContextValue}>
            {/* SFCC-11 plan step 4.6 fix: this used to be `itemCount === 0 ? <hardcoded placeholder> :
                children` — ignoring `children` entirely at zero items, no matter what the caller passed.
                Renders `children` unconditionally now; the empty-vs-populated decision belongs entirely
                to the caller (see ZimmCartDrawerProps.children's own doc above). */}
            <chakra.div __css={styles.body}>{children}</chakra.div>
            {/* 1:1 Figma-alignment audit fix, 2026-09-23 (Marcel's direct report): conditional on
                `footer` itself, not rendered unconditionally with possibly-empty content — the
                wrapper's own `marginTop` (zimmCartDrawer.css.ts's `footer` part) would otherwise
                leave a dead 64px-margined empty box behind whenever a caller omits `footer`
                (the empty-cart case, cartDrawerContainer.tsx), which is a different failure mode
                than `messages` above (that slot deliberately always reserves its height — see
                its own doc comment — `footer` never carried that same requirement). */}
            {footer && (
              // data-testid: same reasoning as scrollArea/items-column's own — lets a test prove
              // this wrapper is genuinely absent (not just empty) when `footer` isn't passed,
              // since ZimmBenefits itself renders `null` with no Contentful data regardless.
              <chakra.div __css={styles.footer} data-testid="cart-footer">
                {footer}
              </chakra.div>
            )}
          </ScrollAreaContext.Provider>
        </chakra.div>
      </chakra.div>
    </ZimmDrawer>
  );
};

